{
  "case_id": "xsu_sg_009_medical_documentation_content",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret rammer kernen (varig funktionsnedsættelse, udrednings- og behandlingsforløb, symptomer, journalminimum). Men det mangler flere kritiske punkter. Det omtaler ikke arten og graden, planlagt behandling eller erhvervsevne. Det udlægger desuden dokumentationen som noget, den \"bør\" beskrive, og som \"helst\" skal vise, selv om bekendtgørelsen og vejledningen siger \"skal\". Svaret fremstiller også L 152-forarbejderne som et forslag uden gældende hjemmel, selv om kilden er vist som støtte. Dette er en væsentlig unøjagtighed."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret dækker udrednings- og behandlingsforløb, aktuelle symptomer og aktualitet. Det mangler eksplicit art og grad, diagnose hvis stillet, planlagt behandling, erhvervsevne hvis muligt samt kravet om, at oplysningerne skal fremsendes, når de er tilgængelige i journalen. Nogle punkter nævnes kun indirekte, og det er ikke nok."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvad den lægelige dokumentation skal beskrive. Afsnittene om flere funktionsnedsættelser og forarbejder er relevante for spørgsmålet."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til identificerbare kilder: SU-bekendtgørelsen, vejledning nr. 10157 og L 152 (2024-25). Påstandene er knyttet til dem med nummererede henvisninger."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "Vejledningen og SU-bekendtgørelsen er gyldige og autoritative. Men L 152-forarbejderne er et lovforslag fra 2025 og dermed ikke den aktuelle autoritative kilde. De bruges til at sige, at diagnose alene eller medicinkort ikke er tilstrækkeligt. Svaret erkender selv, at forslaget ikke er gældende hjemmel. Kildelisten er desuden uklar, da henvisningerne 1-7 ikke tydeligt kan matches til kilderne."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Flere påstande støttes ikke af de viste passager. Det gælder påstanden om, at diagnose alene eller medicinkort ikke er tilstrækkeligt, og påstanden om medfødt funktionsnedsættelse med sygehistorik og seneste journalnotater. Det gælder også, at man skal oplyse, at der søges på flere forhold, og at dokumentationen skal vise, hvordan nedsættelsen viser sig i praksis. De frosne passager viser ikke disse forhold. De støtter heller ikke den juridiske vægtning af forarbejderne."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer krav, som ikke er støttet af materialet: særlige regler for medfødt funktionsnedsættelse, krav om dokumentation for alle funktionsnedsættelser samt oplysning om, at der søges på flere forhold. Det tilføjer også, at et medicinkort ikke er tilstrækkeligt."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Forbeholdene \"hvis diagnose er stillet\", \"hvis behandling er planlagt\" og \"hvis erhvervsevnen kan beskrives\" bevares ikke, fordi punkterne mangler. Forbeholdet om tilgængelighed i journalen mangler også. Svaret bevarer dog \"som udgangspunkt\" i bekendtgørelsens § 37, stk. 2 og nævner aktualitet."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret er internt uens. Det siger først \"skal\" og går derefter over til \"bør\" og \"helst\". Det bruger forarbejder, som det selv kalder et forslag uden hjemmel, til at underbygge kravet om fyldestgørende dokumentation. Konklusionen bygger på et \"mest nærliggende\" grundlag, som ikke følger klart af trinene."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Vejledningen og bekendtgørelsen bruger \"skal\", men svaret svækker det til \"bør\" og \"helst\" for dokumentationens indhold. Det formulerer også påstande om det foreslåede som gældende krav. Det omtaler Udbetaling Danmarks vurdering som begrænset \"som udgangspunkt\", hvilket er rimeligt."
    }
  },
  "xhaile_coverage": {
    "A39": {
      "label": "no",
      "reason": "Svaret nævner ikke, at diagnosen skal oplyses, hvis der er stillet en. Det siger kun, at en ren diagnose ikke er nok."
    },
    "A41": {
      "label": "partial",
      "reason": "Svaret nævner udrednings- og behandlingsforløb og aktuelle symptomer. Sygdomsforløbet nævnes ikke eksplicit, bortset fra \"dens forløb\" i konklusionen."
    },
    "A42": {
      "label": "yes",
      "reason": "Svaret siger, at dokumentationen bør beskrive udrednings- og behandlingsforløb og hvilken behandling der har været."
    },
    "A45": {
      "label": "partial",
      "reason": "Svaret nævner \"eventuelt planlagt\" behandling i tommelfingerreglen, men ikke som krav i kernen, og uden \"hvis der er planlagt en\"."
    },
    "A47": {
      "label": "no",
      "reason": "Svaret nævner ikke påvirkning af erhvervsevnen, hvis muligt."
    }
  },
  "overall_notes": "Svaret dækker kernen: varig funktionsnedsættelse, journalminimum, udrednings- og behandlingsforløb samt aktuelle symptomer. Men det mangler art og grad, diagnose, erhvervsevne og tilgængelighedsforbeholdet. Det svækker \"skal\" til \"bør\" og tilføjer påstande om medfødt funktionsnedsættelse og flere funktionsnedsættelser uden støtte i de frosne passager. Det bruger desuden lovforslag som støtte for en regel."
}

